namespace sv_f76c08f35d0d471aa8b7942ece79994a.Services;

public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private Timer? _timer;
    private int _subscriberCount;
    private readonly object _lock = new();

    public int LowStockCount { get; private set; }

    /// <summary>
    /// Fired when alert data changes. Subscribers must wrap StateHasChanged in InvokeAsync
    /// since this fires from a timer (background thread).
    /// </summary>
    public event Action? OnAlertDataChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning low-stock item count for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Call when a component that needs polling becomes active.
    /// Starts the 10-second poll timer when the first subscriber registers.
    /// </summary>
    public void StartPolling()
    {
        lock (_lock)
        {
            _subscriberCount++;
            if (_subscriberCount == 1)
            {
                _timer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
            }
        }
    }

    /// <summary>
    /// Call when a component that needs polling is disposed/leaves.
    /// Stops the timer when no subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        lock (_lock)
        {
            _subscriberCount = Math.Max(0, _subscriberCount - 1);
            if (_subscriberCount == 0)
            {
                _timer?.Dispose();
                _timer = null;
            }
        }
    }

    private async void PollCallback(object? state)
    {
        var count = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        LowStockCount = count;
        OnAlertDataChanged?.Invoke();
    }

    private void OnWarehouseChanged()
    {
        // When warehouse changes, immediately re-poll so subscribers see fresh data.
        if (_timer is not null)
        {
            _timer.Change(TimeSpan.Zero, TimeSpan.FromSeconds(10));
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        _timer?.Dispose();
    }
}

