@rendermode InteractiveServer
@inject WarehouseState WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label class="form-label mb-0 me-2 text-white">Warehouse:</label>
    <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
            value="@WarehouseState.SelectedWarehouseId"
            @onchange="OnWarehouseSelected">
        @foreach (var (id, name) in WarehouseState.AvailableWarehouses)
        {
            <option value="@id">@name</option>
        }
    </select>
</div>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _handler;
    }

    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        var warehouseId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(warehouseId))
        {
            WarehouseState.SetWarehouse(warehouseId);
        }
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= _handler;
    }
}

@inject InventoryAlertService AlertService
@implements IDisposable

<span class="badge bg-danger ms-2" title="Low stock items">@AlertService.LowStockCount</span>

@code {
